<script setup>import {computed} from 'vue';const props=defineProps({title:String,value:[String,Number],unit:String,accent:String,spark:{type:Array,default:()=>[]},hint:String});const points=computed(()=>{if(props.spark.length<2)return'';const vals=props.spark.map(Number),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1;return vals.map((v,i)=>`${i*72/(vals.length-1)},${24-(v-min)/span*20}`).join(' ')})</script>
<template><article class="kpi" :style="{'--accent':accent}"><div class="kpi-label">{{title}}</div><div class="kpi-value">{{value??'—'}}<small>{{unit}}</small></div><svg v-if="points" class="spark" viewBox="0 0 72 28" preserveAspectRatio="none" aria-hidden="true"><polyline :points="points" /></svg><div v-else class="kpi-pulse"><i></i></div><small class="kpi-hint">{{hint}}</small></article></template>
